parameters.jsCode:
// El nodo AI Agent devuelve 'output'; la cadena simple devuelve 'text'.
// Se leen los dos para que el ejemplo no dependa de cual se use.
function leer(nodo) {
  try {
    const j = $(nodo).first().json;
    const v = (j.output !== undefined && j.output !== null) ? j.output : j.text;
    return (v === undefined || v === null) ? '' : String(v).trim();
  } catch (e) { return ''; }
}

const perfil    = $('El caso: plata, plazo y miedo').first().json.perfil;
const propuesta = leer('Paso 1 - El analista propone');
const objecion  = leer('Paso 2 - El auditor busca el riesgo');
const decision  = leer('Paso 3 - El comite decide');

// Se devuelve todo junto para poder LEER EL PROCESO, no solo el resultado:
// la gracia del ejemplo es ver como cambia la propuesta despues de la auditoria.
return [{
  json: {
    '1_el_caso': perfil,
    '2_lo_que_propuso_el_analista': propuesta,
    '3_lo_que_objeto_el_auditor': objecion,
    '4_lo_que_decidio_el_comite': decision,
    aviso: 'Ejemplo de clase con un caso inventado. No es una recomendacion de inversion.'
  }
}];
